function quoteFromAllianzReference(raw,asset){
  const ref=JSON.parse(raw);
  if(asset.id!=='allianz-pensione'||asset.pensionLine!=='azionaria'||
     ref.product!=='Allianz Previdenza'||ref.line!=='azionaria'||ref.instrument!=='0P0000CX0Z'){
    throw Error('Riferimento Allianz non corrispondente alla Linea Azionaria');
  }
  const price=Number(ref.price);
  if(!Number.isFinite(price)||price<=0||!isValidDate(ref.date))throw Error('NAV storico non valido');
  return packQuote(asset,price,ref.date,
    'Riferimento storico verificato · '+ref.source+' · NON live',
    {verifiedReference:true,pensionLine:'azionaria',navFrequency:'settimanale'});
}
